"""Smoke-test an exported synthetic transfer as an independent local application."""
import argparse
import json
import selectors
import subprocess
import sys
import tempfile
import time
import urllib.request
import zipfile
from pathlib import Path


def run(archive, output):
    with tempfile.TemporaryDirectory(prefix="chair_portable_launch_") as temporary:
        base = Path(temporary)
        with zipfile.ZipFile(archive) as z:
            # This test consumes an archive generated by our synthetic browser test.
            for name in z.namelist():
                if not (base / name).resolve().is_relative_to(base):
                    raise ValueError("Archive path escapes test directory")
            z.extractall(base)
        app = base / "ChairLogAnnotator"
        process = subprocess.Popen([sys.executable, "-u", "-X", "utf8", str(app / "launcher.py"), "--no-browser"],
                                   cwd=base, stdout=subprocess.PIPE, stderr=subprocess.STDOUT)
        url, collected = None, b""
        try:
            selector = selectors.DefaultSelector()
            selector.register(process.stdout, selectors.EVENT_READ)
            deadline = time.monotonic() + 10
            while time.monotonic() < deadline and url is None:
                for key, _ in selector.select(.1):
                    data = key.fileobj.read1(4096)
                    if not data:
                        raise RuntimeError("Launcher exited: " + collected.decode("utf-8", "replace"))
                    collected += data
                    for line in collected.decode("utf-8").splitlines():
                        if line.startswith("http://127.0.0.1:"):
                            url = line.strip()
            if url is None:
                raise RuntimeError("Timed out waiting for packaged launcher")
            def call(route, body=None, token=None):
                request = urllib.request.Request(url.rstrip("/") + route,
                    data=json.dumps(body).encode() if body is not None else None,
                    headers={"Content-Type": "application/json", "X-Annotation-Token": token or ""})
                with urllib.request.urlopen(request, timeout=10) as response:
                    return json.load(response)
            config = call("/api/config")
            assert config["app_release"] == "1.1-portable"
            cases = call("/api/cases")
            assert len(cases) == 1 and cases[0]["case_id"] == "2000-01-01__TEST__Chair_log_seq_1"
            record = call("/api/case?id=" + cases[0]["case_id"])
            doc = record["document"]
            assert len(doc["intervals"]) == 2
            assert doc["intervals"][0]["treatment_jp"] == "う蝕除去"
            old = doc["revision"]
            doc["intervals"][0]["notes"] += "・移行後の再編集"
            doc["intervals"][0]["reviewed"] = False
            saved = call("/api/save", doc, config["token"])["document"]
            assert saved["revision"] == old + 1
            exported = call("/api/export", {"case_id": doc["case_id"], "revision": saved["revision"], "mode": "draft"}, config["token"])
            with urllib.request.urlopen(url.rstrip("/") + exported["url"], timeout=10) as response:
                assert response.read(2) == b"PK"
            result = {"passed": True, "platform": sys.platform, "python": sys.version.split()[0],
                      "checks": ["packaged launcher starts independently", "bundled data selected automatically",
                                 "ephemeral port and Host/CSRF checks work", "Japanese annotations restored",
                                 "editing creates next revision", "export downloads after relocation"],
                      "windows_macos_native_execution_tested": False}
            output.write_text(json.dumps(result, ensure_ascii=False, indent=2), encoding="utf-8")
            print(json.dumps(result, ensure_ascii=False))
        finally:
            process.terminate()
            try:
                process.wait(timeout=5)
            except subprocess.TimeoutExpired:
                process.kill()
                process.wait()


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("archive", type=Path)
    parser.add_argument("--output", type=Path, required=True)
    args = parser.parse_args()
    run(args.archive, args.output)
